/* Start here entry for photon-interactions (demos/lib/starthere/photon-interactions.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"Gram for gram, does lead stop 1 MeV gamma rays better than water?","q_es":"Gramo por gramo, ¿el plomo detiene los rayos gamma de 1 MeV mejor que el agua?","setup":"set=selMat~pb!sE~3!chkParts~1!chkTr~1!chkEn~1!labBlind~0!g%3Apresets~lead1","do":"This is lead at 1 MeV. Decide how lead's attenuation per gram compares with water's, then read <b>μ/ρ</b> and <b>Half value layer</b>. Pick <b>Water, liquid</b> under <b>Material</b> and read them again.","do_es":"Es plomo a 1 MeV. Decide cómo se compara la atenuación por gramo del plomo con la del agua, luego lee <b>μ/ρ</b> y <b>Capa hemirreductora</b>. Elige <b>Agua, líquida</b> en <b>Material</b> y vuelve a leerlas.","see":"Per gram they are almost equal: μ/ρ is 0.07102 cm²/g for lead and 0.07072 cm²/g for water. At 1 MeV most photons are Compton scattered by electrons, and lead has fewer electrons per gram (Z/A = 0.396 against 0.555), so its photoelectric share, 25.5 %, only makes up the difference. Lead's half value layer, 0.8599 cm against 9.801 cm, is shorter because lead is 11.35 times as dense.","see_es":"Por gramo son casi iguales: μ/ρ es 0.07102 cm²/g para el plomo y 0.07072 cm²/g para el agua. A 1 MeV la mayoría de los fotones sufren dispersión Compton con los electrones, y el plomo tiene menos electrones por gramo (Z/A = 0.396 contra 0.555), así que su parte fotoeléctrica, 25.5 %, solo compensa la diferencia. La capa hemirreductora del plomo, 0.8599 cm contra 9.801 cm, es más corta porque el plomo es 11.35 veces más denso.","explore":[{"setup":"set=selMat~bone!sE~1.477!chkParts~1!chkTr~1!chkEn~1!labBlind~0!g%3Apresets~bone30","do":"<b>Bone against soft tissue, 30 keV</b>: cortical bone at 30 keV. Decide how many times as much bone attenuates per gram as soft tissue, then read <b>μ/ρ</b> and the <b>Photoelectric</b> share. Pick <b>Soft tissue (ICRU 44)</b> under <b>Material</b> and read them again.","do_es":"<b>Hueso frente a tejido blando, 30 keV</b>: hueso cortical a 30 keV. Decide cuántas veces más atenúa el hueso por gramo que el tejido blando, luego lee <b>μ/ρ</b> y la parte <b>Fotoeléctrico</b>. Elige <b>Tejido blando (ICRU 44)</b> en <b>Material</b> y vuelve a leerlas.","see":"Bone has 1.331 cm²/g, 80.9 % of it photoelectric; soft tissue has 0.3790 cm²/g, 40.1 % photoelectric, so bone attenuates 3.5 times as much per gram. The photoelectric effect per atom grows roughly as Z⁴, and the calcium (Z = 20) and phosphorus (Z = 15) in bone make its shadow on a radiograph.","see_es":"El hueso tiene 1.331 cm²/g, el 80.9 % fotoeléctrico; el tejido blando tiene 0.3790 cm²/g, el 40.1 % fotoeléctrico, así que el hueso atenúa 3.5 veces más por gramo. El efecto fotoeléctrico por átomo crece aproximadamente como Z⁴, y el calcio (Z = 20) y el fósforo (Z = 15) del hueso forman su sombra en una radiografía."},{"setup":"set=selMat~water!sE~2.8205!sT~20!selN~20000!labBlind~0!g%3AviewSeg~beam!g%3Apresets~cs137","do":"<b>Cs 137 through water</b>: 661.7 keV photons through 20 cm of water, where the exponential law gives <b>Narrow beam e^(−μt)</b> = 0.1802. The photons go as the setup opens. Decide whether the dose behind the slab is more or less than that, then read <b>Narrow beam T</b> and <b>Broad beam K/K₀</b> when the run ends.","do_es":"<b>Cs 137 a través de agua</b>: fotones de 661.7 keV a través de 20 cm de agua, donde la ley exponencial da <b>Haz estrecho e^(−μt)</b> = 0.1802. Los fotones salen en cuanto se abre la configuración. Decide si la dosis detrás de la placa es mayor o menor que eso, luego lee <b>T de haz estrecho</b> y <b>K/K₀ de haz ancho</b> cuando termine la corrida.","see":"T = 0.1780 ± 0.0027 agrees with e^(−μt): those are the photons that never interacted. K/K₀ = 0.4490 is 2.492 times larger (<b>Buildup B</b>), because photons scattered on the way reach the far side too. A shield designed with the exponential law alone lets through more than twice the dose it was designed for.","see_es":"T = 0.1780 ± 0.0027 coincide con e^(−μt): son los fotones que nunca interactuaron. K/K₀ = 0.4490 es 2.492 veces mayor (<b>Acumulación B</b>), porque los fotones dispersados en el camino también llegan al otro lado. Un blindaje diseñado solo con la ley exponencial deja pasar más del doble de la dosis para la que se diseñó."},{"setup":"set=sKv~80!sAl~2.5!selF2~cu!sF2~0!labBlind~0!g%3AviewSeg~hard!g%3Apresets~tube80","do":"<b>80 kVp diagnostic beam</b> with 2.5 mm of aluminum. The first half value layer of aluminum halves the air kerma, and the second halves it again. Decide whether the second is as thick as the first, then read <b>HVL₁ (Al)</b> and <b>HVL₂ (Al)</b>.","do_es":"<b>Haz de diagnóstico de 80 kVp</b> con 2.5 mm de aluminio. La primera capa hemirreductora de aluminio reduce a la mitad el kerma en aire, y la segunda lo reduce a la mitad otra vez. Decide si la segunda es tan gruesa como la primera, luego lee <b>HVL₁ (Al)</b> y <b>HVL₂ (Al)</b>.","see":"HVL₁ is 2.740 mm and HVL₂ is 4.093 mm. The aluminum takes out the low energy photons first, so the beam that is left is harder and gets through the next layer more easily. For photons of one energy the two would be equal; here <b>Homogeneity h = HVL₁/HVL₂</b> is 0.669.","see_es":"HVL₁ es 2.740 mm y HVL₂ es 4.093 mm. El aluminio quita primero los fotones de baja energía, así que el haz que queda es más duro y atraviesa la siguiente capa con más facilidad. Para fotones de una sola energía las dos serían iguales; aquí <b>Homogeneidad h = HVL₁/HVL₂</b> es 0.669."}]});
